<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Review Order | Chick N Lick</title><script src="https://cdn.tailwindcss.com"></script></head>
<body class="min-h-screen bg-[#fff9f5] pb-24 text-[#171411]"><header class="border-b bg-white px-5 py-4"><div class="mx-auto flex max-w-6xl items-center justify-between"><a href="{{ route('orders') }}" class="font-bold text-[#bd160c]">← Chick N Lick</a><span class="text-sm font-semibold">{{ $email }}</span></div></header>
<main class="mx-auto grid max-w-6xl gap-5 p-5 lg:grid-cols-[1.4fr_1fr]"><section class="space-y-4"><div><h1 class="text-2xl font-bold">Review Commissary Order</h1><p class="mt-1 text-sm text-[#765f56]">Confirm your products and delivery details.</p></div><div id="cartItems" class="space-y-3"></div><p id="emptyCart" class="hidden rounded-xl border border-dashed bg-white p-8 text-center text-[#765f56]">Your cart is empty.</p></section><section class="space-y-4"><div class="rounded-xl border bg-white p-4"><h2 class="font-bold">Delivery &amp; Logistics</h2><div class="mt-4 space-y-3"><label class="block text-sm font-bold">Delivery Location<input name="delivery_address" class="mt-1 w-full rounded-lg border p-3" placeholder="Enter delivery address"></label><label class="block text-sm font-bold">Preferred Delivery Date<input name="delivery_date" type="date" class="mt-1 w-full rounded-lg border p-3"></label><label class="block text-sm font-bold">Special Instructions<textarea name="special_instructions" rows="3" class="mt-1 w-full rounded-lg border p-3" placeholder="Add delivery instructions"></textarea></label></div></div><div class="rounded-xl border bg-white p-4"><div class="flex justify-between"><span>Subtotal</span><strong id="subtotal">₱0.00</strong></div><button id="submitOrder" class="mt-5 w-full rounded-lg bg-[#ffd21f] px-4 py-3 font-bold">Submit Purchase Order</button></div></section></main>
<div id="confirmModal" class="fixed inset-0 z-[100] hidden items-center justify-center bg-[#171411]/60 p-4"><div class="w-full max-w-md rounded-2xl border-2 border-[#171411] bg-[#fff9f5] p-6 shadow-2xl"><div class="flex items-center gap-3 border-b border-[#eadfd8] pb-4"><div class="flex h-11 w-11 items-center justify-center rounded-xl bg-[#ffd21f] text-xl">🍗</div><div><p class="text-xs font-bold uppercase tracking-[.18em] text-[#e56d15]">Chick N Lick</p><h2 class="text-lg font-bold">Confirm Purchase Order</h2></div></div><p class="mt-5 text-sm text-[#765f56]">Are you sure you want to submit this purchase order?</p><div class="mt-6 flex justify-end gap-3"><button id="cancelConfirm" type="button" class="rounded-lg border border-[#d5cbb9] bg-white px-5 py-2.5 font-bold">Cancel</button><button id="approveConfirm" type="button" class="rounded-lg bg-[#ffd21f] px-5 py-2.5 font-bold shadow-sm">Submit Order</button></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const brandedConfirm=()=>new Promise(resolve=>{const modal=document.getElementById('confirmModal');modal.classList.remove('hidden');modal.classList.add('flex');const close=(result)=>{modal.classList.add('hidden');modal.classList.remove('flex');resolve(result)};document.getElementById('cancelConfirm').onclick=()=>close(false);document.getElementById('approveConfirm').onclick=()=>close(true)});const cart=JSON.parse(localStorage.getItem('vibe-cart-items-{{ md5($email) }}')||'[]');const list=document.getElementById('cartItems');const empty=document.getElementById('emptyCart');const total=cart.reduce((sum,item)=>sum+Number(item.price||0)*Number(item.quantity||0),0);document.getElementById('subtotal').textContent=`₱${total.toFixed(2)}`;if(!cart.length){empty.classList.remove('hidden');return;}list.innerHTML=cart.map(item=>`<div class="flex items-center justify-between rounded-xl border bg-white p-4"><div><h3 class="font-bold">${item.name}</h3><p class="text-sm text-[#765f56]">${item.quantity} × ${item.unit||'piece'} @ ₱${Number(item.price||0).toFixed(2)}</p></div><strong>₱${(Number(item.price||0)*Number(item.quantity||0)).toFixed(2)}</strong></div>`).join('');document.getElementById('submitOrder').addEventListener('click',async()=>{if(!await brandedConfirm())return;const form=document.createElement('form');form.method='POST';form.action='{{ route('cart.submit') }}';const fields={order_items:JSON.stringify(cart),order_total:total.toFixed(2),delivery_address:document.querySelector('[name="delivery_address"]').value,special_instructions:document.querySelector('[name="special_instructions"]').value,_token:'{{ csrf_token() }}'};Object.entries(fields).forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;form.appendChild(input);});localStorage.removeItem('vibe-cart-items-{{ md5($email) }}');document.body.appendChild(form);form.submit();});});</script><x-bottom-nav :email="$email" /></body></html>


